# Check that our rule doesn't over-apply to other strings
inputs = ['vidb', 'vvxack', 'cdc', 'iic', 'vd']
outputs = ['vidb', 'viccev', 'cdc', 'iic', 'vd']

rule = ('vxack', 'iccev')

print("Checking for over-applications:")
for i, inp in enumerate(inputs):
    # Apply the rule
    result = inp.replace(rule[0], rule[1])
    expected = outputs[i]

    if inp != expected:
        print(f"  String {i}: '{inp}' -> '{result}' (should be '{expected}')")
    else:
        print(f"  String {i}: '{inp}' -> '{result}' (correctly unchanged)")

    # Check if this would be an over-application (if input equals output but result doesn't)
    if inp == expected and result != expected:
        print(f"    ERROR: Over-application detected!")

print("\nVerifying no unintended modifications:")
# Check if 'vxack' appears anywhere else besides the intended case
for i, inp in enumerate(inputs):
    if 'vxack' in inp and inp != 'vvxack':
        print(f"Warning: 'vxack' found in string {i}: '{inp}'")
    elif inp == 'vvxack':
        print(f"String {i}: '{inp}' contains 'vxack' - this should be transformed")
    else:
        print(f"String {i}: '{inp}' - no 'vxack' to transform")

